pub fn Exhaustive_Monitor_C_OperatingState_strategy_default() -> impl Strategy<Value = Exhaustive_Monitor_C::OperatingState>
{
  Exhaustive_Monitor_C_OperatingState_strategy_cust(1, 1, 1)
}

pub fn Exhaustive_Monitor_C_OperatingState_strategy_cust(
  Idle_bias: u32,
  Active_bias: u32,
  Fault_bias: u32) -> impl Strategy<Value = Exhaustive_Monitor_C::OperatingState>
{
  prop_oneof![
    Idle_bias => Just(Exhaustive_Monitor_C::OperatingState::Idle),
    Active_bias => Just(Exhaustive_Monitor_C::OperatingState::Active),
    Fault_bias => Just(Exhaustive_Monitor_C::OperatingState::Fault)
  ]
}

pub fn Exhaustive_Monitor_C_Samples_strategy_default() -> impl Strategy<Value = Exhaustive_Monitor_C::Samples>
{
  Exhaustive_Monitor_C_Samples_strategy_cust(any::<i32>())
}

pub fn Exhaustive_Monitor_C_Samples_strategy_cust<i32_strategy: Strategy<Value = i32>> (base_strategy: i32_strategy) -> impl Strategy<Value = Exhaustive_Monitor_C::Samples>
{
  proptest::collection::vec(base_strategy, Exhaustive_Monitor_C::Exhaustive_Monitor_C_Samples_DIM_0)
    .prop_map(|v| {
      let boxed: Box<[i32; Exhaustive_Monitor_C::Exhaustive_Monitor_C_Samples_DIM_0]> = v.into_boxed_slice().try_into().unwrap();
      *boxed
  })
}

